head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getHeaderIndex]<br/>Header Column 의 ID 를 사용하여 특정 Header Column 의 인덱스값을 반환합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 인덱스값을 조회할 Header Column 의 ID 를 설정할 수 있어야 합니다.",
        "파라미터에 해당하는 Header Column 의 인덱스값을 반환해야 합니다. (인덱스는 0 부터 시작하며 숨겨진 Column 도 포함)",
        "파라미터에 해당하는 Header Column 이 없는 경우 undefined 를 반환해야 합니다.",
        "RowNum, RowStatus Column 은 인덱스에 포함되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="column2(인덱스 1)는 숨김 처리됨 — 숨겨진 Column 도 인덱스에 포함되어 getHeaderIndex(column2)는 여전히 1 을 반환"', '', 'label1');

    // RowNum / RowStatus Header 표시 (validation #4 : 인덱스 제외 대상 컬럼)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
        rowStatusVisible: "true",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 기본 gridView 생성 (Header : column1~column4, Body : col1~col4)
    await $c.gcm.createBasicGridView(cList);

    // column2(인덱스 1) 숨김 (숨겨진 Column 도 인덱스에 포함됨을 검증)
    target1.setColumnVisible(1, false);
}



scwin.btn_getHeaderIndex_onclick = function () {
    let headerId = par_headerId.getValue();

    let rtn = target1.getHeaderIndex(headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderIndex('" + headerId + "') : " + rtn);
}
